import{a}from"./chunks/theme.CNGxYoQx.js";import{B as n,o,c as r,ax as i,E as s,k as p}from"./chunks/framework.Bnt0oLax.js";const f=JSON.parse('{"title":"API Reference | Create an event","description":"","frontmatter":{"title":"API Reference | Create an event","aside":true},"headers":[],"relativePath":"api/operations/events/createEvent.md","filePath":"api/operations/events/createEvent.md"}'),d={name:"api/operations/events/createEvent.md"},h=Object.assign(d,{setup(l){return(c,e)=>{const t=n("OAOperation");return o(),r("div",null,[e[0]||(e[0]=i('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/api/operations/events/createEvent.md for this page in Markdown format</div><h1 id="create-an-event" tabindex="-1">Create an event <a class="header-anchor" href="#create-an-event" aria-label="Permalink to &quot;Create an event&quot;">​</a></h1><p><span class="OA-tag">Events</span></p><p>Moderators can create an event with a title, description, event timezone, event start time/date, and event end time/date. Events do not have a category.</p><p>Events can be created and published immediately, or can be created as draft and published later. Draft events are not publicly visible.</p><p>Optionally, moderators can provide a location for an event, as well as a URL for end users to find more information or formally register for an event. Moderators can optionally set a display label for a URL, to provide more context for the end user about the link.</p><p>In addition, moderators can specify an event type for the event (a label highlighting the type of event, e.g. Webinar, Conference, Meetup).</p><p>Moderators can also add a custom confirmation message that is shown to end users after they press attend; for example, to highlight any actions that the end user needs to take external to the community.</p><p>Events can also optionally have a featured image with a valid url. The allowed image extensions for featured image are png, jpeg, jpg, gif.</p>',9)),s(t,{"operation-id":"createEvent",spec:p(a)},null,8,["spec"])])}}});export{f as __pageData,h as default};
